import 'jest';
import { generateGuid, getGreatestCommonDivider } from '../../src';

describe('Math', () => {
    describe('guidString()', () => {
        let mathRandomSpy: jest.SpyInstance;

        beforeEach(() => {
            mathRandomSpy = jest.spyOn(global.Math, 'random');
        });

        afterEach(() => {
            jest.spyOn(global.Math, 'random').mockRestore();
        });

        it('will return a valid guid', () => {
            const guid = generateGuid();

            expect(mathRandomSpy).toBeCalledTimes(4);
            expect(typeof guid === 'string').toBe(true);
            expect((guid.match(/\-/g) || []).length).toBe(4);
        });
    });

    describe('getGreatestCommonDivider()', () => {
        it('will find the greatest common value that both values can by divided by', () => {
            expect(getGreatestCommonDivider(20, 100)).toBe(20);
            expect(getGreatestCommonDivider(8, 20)).toBe(4);
            expect(getGreatestCommonDivider(5, 13)).toBe(1);
        });
    });

    describe('mod()', () => {
        it('will find the modulus value for two given numbers', () => {
            // Added % (remainder operation) side-by-side to demonstrate difference
            expect(Math.mod(10, 3)).toBe(1);
            expect(10 % 3).toBe(1);

            expect(Math.mod(-10, 3)).toBe(2);
            expect(-10 % 3).toBe(-1);

            expect(Math.mod(22, 7)).toBe(1);
            expect(22 % 7).toBe(1);

            expect(Math.mod(-13, 4)).toBe(3);
            expect(-13 % 4).toBe(-1);

            expect(Math.mod(-19, 7)).toBe(2);
            expect(-19 % 7).toBe(-5);
        });
    });

    describe('sortAscending()', () => {
        it('will return a positive value if the first number is larger than the second number', () => {
            expect(Math.sortAscending(10, 1)).toBeGreaterThan(0);
        });

        it('will return a negative value if the first number is smaller than the second number', () => {
            expect(Math.sortAscending(3, 50)).toBeLessThan(0);
        });

        it('will return a 0 if both values are the same', () => {
            expect(Math.sortAscending(5, 5)).toBe(0);
        });
    });

    describe('sortDescending()', () => {
        it('will return a negative value if the first number is larger than the second number', () => {
            expect(Math.sortDescending(10, 1)).toBeLessThan(0);
        });

        it('will return a positive value if the first number is smaller than the second number', () => {
            expect(Math.sortDescending(3, 50)).toBeGreaterThan(0);
        });

        it('will return a 0 if both values are the same', () => {
            expect(Math.sortDescending(5, 5)).toBe(0);
        });
    });

    describe('clamp()', () => {
        it('will clamp a number if it exceeds the min/max range', () => {
            expect(Math.clamp(-1)).toBe(0);
            expect(Math.clamp(2)).toBe(1);
            expect(Math.clamp(-5, -2, 2)).toBe(-2);
            expect(Math.clamp(5, -2, 2)).toBe(2);
        });

        it('will not clamp a number if its within the min/max range', () => {
            expect(Math.clamp(0.2)).toBe(0.2);
            expect(Math.clamp(-1, -2, 2)).toBe(-1);
            expect(Math.clamp(1, -2, 2)).toBe(1);
        });
    });

    describe('remapClamp()', () => {
        it('will remap and clamp values to a default min/max range of 0-1', () => {
            expect(Math.remapClamp(150, 0, 100)).toBe(1);
            expect(Math.remapClamp(-50, 0, 100)).toBe(0);
        });

        it('will remap and clamp values to a custom min/max range', () => {
            expect(Math.remapClamp(150, 0, 100, 0, 10)).toBe(10);
            expect(Math.remapClamp(-50, 0, 100, -10, 0)).toBe(-10);
        });

        it('will remap and not clamp values if they are within the range', () => {
            expect(Math.remapClamp(50, 0, 100)).toBe(0.5);
            expect(Math.remapClamp(50, 0, 100, 0, 10)).toBe(5);
        });
    });

    describe('remap()', () => {
        it('will remap a value to a default range', () => {
            expect(Math.remap(20, 0, 100)).toBe(0.2);
            expect(Math.remap(75, 0, 100)).toBe(0.75);
            expect(Math.remap(150, 0, 100)).toBe(1.5);
            expect(Math.remap(-50, 0, 100)).toBe(-0.5);
        });

        it('will remap a value to a custom range', () => {
            expect(Math.remap(20, 0, 100, 0, 10)).toBe(2);
            expect(Math.remap(75, 0, 100, 0, 10)).toBe(7.5);
            expect(Math.remap(150, 0, 100, 0, 10)).toBe(15);
            expect(Math.remap(-50, 0, 100, 0, 10)).toBe(-5);
        });
    });

    describe('smoothStep()', () => {
        it('will return correct value for a given step', () => {
            expect(Math.smoothStep(0)).toBe(0);
            expect(Math.smoothStep(0.5)).toBe(0.5);
            expect(Math.smoothStep(0.8)).toBe(0.8960000000000001);
            expect(Math.smoothStep(1)).toBe(1);
        });
    });

    describe('smootherStep()', () => {
        it('will return correct value for a given step', () => {
            expect(Math.smootherStep(0)).toBe(0);
            expect(Math.smootherStep(0.5)).toBe(0.5);
            expect(Math.smootherStep(0.8)).toBe(0.9420800000000001);
            expect(Math.smootherStep(1)).toBe(1);
        });
    });

    describe('roundToNearestMultiple()', () => {
        it('will round to nearest multiple for a given value and multipler', () => {
            expect(Math.roundToNearestMultiple(8, 3)).toBe(9);
            expect(Math.roundToNearestMultiple(50, 3)).toBe(51);
            expect(Math.roundToNearestMultiple(30, 16)).toBe(32);
        });
    });

    describe('interpolate()', () => {
        it('will interpolate between two values at a given step', () => {
            expect(Math.interpolate(0, 100, 0.5)).toBe(50);
            expect(Math.interpolate(0, 100, 0.1)).toBe(10);
            expect(Math.interpolate(0, 8, 0.5)).toBe(4);
        });
    });
});